'use strict';
state.config.welcomeMessage ??= '你好！歡迎使用，請輸入關鍵詞查看資訊。';
state.config.botDescription ??= '';
const runtime={keys:{},results:{},models:{},nextPages:{},busy:false,googleToken:'',expiresAt:0,revision:null,sheetId:'',sheetTitle:'',sheetStatus:'尚未授權',remoteRules:null};
if(!Array.isArray(state.rules))state.rules=[{id:'rule-welcome',enabled:true,keyword:'你好',match:'contains',type:'text',text:'你好！歡迎使用課程小幫手，輸入「報名」查看說明。',url:''},{id:'rule-apply',enabled:true,keyword:'報名',match:'contains',type:'text',text:'請先聯絡課程管理者取得報名網址。你可以編輯這筆規則，改成自己的網址回覆。',url:''}];
state.config.aiEnabled=state.config.aiEnabled===true;state.config.ragEnabled=state.config.ragEnabled===true;
function apiEndpoint(){const base=state.config.apiBase||'';if(!base)return new URL('/.netlify/functions/relay-api',location.href).href;return new URL('/.netlify/functions/relay-api',base).href}
async function callApi(payload){if(location.hostname?.endsWith('.github.io')&&!state.config.apiBase)throw Error('GitHub Pages 尚未設定 API 後端。請展開「進階：測試後端連線」，填入自己部署的 Netlify 來源後再測試。');let response;try{response=await fetch(apiEndpoint(),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload),cache:'no-store',signal:AbortSignal.timeout(35000)})}catch{throw Error('無法連接測試後端。請使用本機啟動程式或 Netlify 完整部署；GitHub Pages 需設定後端網址。')}let data;try{data=await response.json()}catch{throw Error('目前是靜態預覽，未啟動 API 服務。請使用 npm start 或完整部署到 Netlify。')}if(!response.ok)throw Error(data.error||'服務連線失敗。');return data}
function connectionSettings(){openModal('測試服務連線',`<p>本機啟動程式與 Netlify 完整部署可直接使用。GitHub Pages 請填入你自己部署的 Netlify 網站來源。</p><label class="field"><span>後端網站來源（留空使用目前網站）</span><input id="api-base" type="url" value="${escapeHTML(state.config.apiBase||'')}" placeholder="https://your-site.netlify.app"><small>API Key 與 Google 授權 Token 會經過這個後端，僅填入你信任及管理的服務。</small></label>`,button('取消','close-modal')+button('保存後端網址','save-api-base','check','primary'))}
actions['save-api-base']=()=>{const value=document.querySelector('#api-base').value.trim();if(value){try{const u=new URL(value);if(u.protocol!=='https:'||u.username||u.password||u.pathname!=='/'||u.search||u.hash)throw Error()}catch{toast('請輸入只有網域的 HTTPS 來源，不含路徑或帳密。');return}}state.config.apiBase=value;save();closeModal();render();toast('已保存服務來源。')};
actions['connection-settings']=connectionSettings;
function apiTestCard(){const result=runtime.results[selectedProvider];return `<section class="panel wizard-card section-space"><h2>AI 連線設定</h2><label class="setting-item"><span><strong>啟用 AI 回答</strong><p>沒有命中關鍵詞時，讓 Bot 使用 AI 回答。不需要 RAG。</p></span><input id="ai-enabled" type="checkbox" ${state.config.aiEnabled?'checked':''}></label><p>不必啟用 AI 回答，也可以先檢查 Key。Key 僅保留在目前頁面記憶體，不寫入本機儲存或試算表。</p><div class="provider-grid">${[['OpenAI','◎'],['Gemini','✦'],['Grok','𝕏']].map(([name,mark])=>`<button class="panel provider ${selectedProvider===name?'selected':''}" data-provider="${name}" aria-pressed="${selectedProvider===name}"><div class="provider-logo">${mark}</div><strong>${name}</strong></button>`).join('')}</div><label class="field"><span>${selectedProvider} API Key</span><input id="live-api-key" type="password" autocomplete="off" spellcheck="false" placeholder="貼上你的 API Key"><small>按測試時經由 ${escapeHTML(state.config.apiBase||'目前網站後端')} 傳至 ${selectedProvider}。</small></label><div class="actions">${button('取得模型清單','list-live-models','refresh')}${runtime.nextPages[selectedProvider]?button('載入更多模型','more-live-models','plus'):''}${button('清除 Key','clear-live-key','trash')}</div><label class="field" style="margin-top:20px"><span>模型名稱</span><input id="manual-model" list="live-model-options" value="${escapeHTML(state.config.provider===selectedProvider?state.config.model:'')}" placeholder="取得清單後選擇，或輸入完整模型名稱"><datalist id="live-model-options">${(runtime.models[selectedProvider]||[]).map(m=>`<option value="${escapeHTML(m)}"></option>`).join('')}</datalist><small>清單中的模型仍需實際呼叫；部分模型不支援文字測試。</small></label>${button(runtime.busy?'測試中…':'送出一次文字測試','test-live-model','play','primary')}<p class="note">測試只送出「回覆 OK」，輸出上限 512 tokens，可能產生少量 API 費用。沒有自動重試。</p><div id="api-test-result" class="status-banner ${result?.error?'warn':''}" aria-live="polite" style="margin-top:18px">${escapeHTML(result?.message||'尚未測試。')}</div><p class="note"><strong>正式 LINE Bot 連線：</strong>下載 GAS 後，在 Apps Script「專案設定 → 指令碼屬性」新增 <code>AI_API_KEY</code>，填入同一組 Key。模型與 Prompt 則從「Setting」工作表讀取。網頁中的 Key 僅用於測試，重新整理後會清除，不隨程式或設定表匯出。</p><details class="wizard-details"><summary>進階：測試後端連線${page==='settings'?'':'與 Prompt'}</summary>${page==='settings'?'':`<label class="field"><span>AI 基本 Prompt（與步驟二同步）</span><textarea id="live-role">${escapeHTML(state.config.role)}</textarea></label>`}${button('設定測試後端','connection-settings','link')}</details></section>`}
function restoreLiveInputs(){const input=document.querySelector('#live-api-key');if(input)input.value=runtime.keys[selectedProvider]||'';if(runtime.busy)document.querySelectorAll('[data-action="test-live-model"],[data-action="list-live-models"],[data-action="more-live-models"]').forEach(b=>b.disabled=true)}
async function runModel(action,more=false){if(runtime.busy)return;const provider=selectedProvider,key=(runtime.keys[provider]||'').trim(),model=document.querySelector('#manual-model')?.value.trim();if(!key){toast('請先輸入 API Key。');return}if(action==='test'&&!model){toast('請先選擇模型。');return}state.config.provider=provider;state.config.model=model||'';save();runtime.busy=true;runtime.results[provider]={message:action==='list'?'正在取得模型清單…':'正在向供應商實際發送測試…'};render();try{const result=await callApi({service:'models',provider,action,apiKey:key,model,...(more?{pageToken:runtime.nextPages[provider]}:{})});if(runtime.keys[provider]!==key)return;if(action==='list'){runtime.models[provider]=[...new Set([...(more?runtime.models[provider]||[]:[]),...result.models])];runtime.nextPages[provider]=result.nextPageToken;runtime.results[provider]={message:`取得 ${runtime.models[provider].length} 個模型名稱，尚未驗證實際可用性。${result.nextPageToken?'可載入下一頁。':''}`}}else{runtime.results[provider]={message:`測試成功：${result.model}\n回覆：${result.text}\n耗時：${result.latencyMs} ms\n時間：${result.testedAt}\n用量：${JSON.stringify(result.usage||'供應商未提供')}`,model:result.model}}}catch(e){if(runtime.keys[provider]===key)runtime.results[provider]={error:true,message:e.message}}finally{runtime.busy=false;if(page==='models'||page==='settings')render()}}
actions['list-live-models']=()=>runModel('list');actions['more-live-models']=()=>runModel('list',true);actions['test-live-model']=()=>runModel('test');actions['clear-live-key']=()=>{delete runtime.keys[selectedProvider];delete runtime.results[selectedProvider];delete runtime.models[selectedProvider];delete runtime.nextPages[selectedProvider];render();toast('已清除本頁的 API Key。')};
function ruleError(rules){if(rules.length>100)return '最多可設定 100 筆規則。';for(const r of rules){if(!r.keyword.trim()||r.keyword.length>200)return '關鍵詞必填，且不可超過 200 字。';if(!r.text.trim()||r.text.length>4000)return '顯示文字必填，且不可超過 4000 字。';if(r.type==='url'){try{const u=new URL(r.url);if(!['http:','https:'].includes(u.protocol)||u.username||u.password||r.url.length>1000)throw Error()}catch{return '請輸入有效的 http 或 https 網址。'}}}return ''}
function rulesPage(){return `<section class="panel wizard-card section-space"><h2>Bot 基本資訊</h2><p>先設定 Bot 的名稱與訊息，再往下新增關鍵詞回覆。</p><label class="field"><span>Bot 名稱（必填）</span><input id="rules-bot-name" maxlength="80" value="${escapeHTML(state.config.botName)}"><small>用於本工具預覽與匯出設定；LINE 官方帳號名稱需在 LINE 後台修改。</small></label><label class="field"><span>Bot 簡介（選填）</span><input id="rules-bot-description" maxlength="200" placeholder="例如：提供課程資訊與報名協助" value="${escapeHTML(state.config.botDescription)}"></label><label class="field"><span>歡迎訊息</span><textarea id="rules-welcome" maxlength="2000">${escapeHTML(state.config.welcomeMessage)}</textarea><small>用於聊天預覽與匯出設定；正式加入好友時的發送需由 LINE 入口串接。</small></label><label class="field"><span>AI 基本 Prompt（角色與回答規則）</span><textarea id="rules-ai-prompt" rows="7" placeholder="例如：你是課程助理。請以繁體中文、親切簡潔的語氣回答。只回答課程相關問題；不確定時請說明，不要編造資訊。">${escapeHTML(state.config.role)}</textarea><small>設定 AI 的角色、語氣、回答範圍與限制。修改後自動保存，並匯出為 Setting 的 AI_ROLE。</small></label><p class="note">使用 AI 回答時才套用此 Prompt，不需要啟用 RAG。請在下方「AI 連線設定」填入 Key、選擇模型並啟用 AI 回答；本機規則預覽不會呼叫 AI。</p><label class="field"><span>預設回覆（必填）</span><textarea id="rules-fallback" maxlength="2000">${escapeHTML(state.config.fallback)}</textarea><small>沒有符合關鍵詞，且未使用 AI 或 RAG 回答時顯示。</small></label><p class="note">修改後自動保存在本機。${button('匯出基本資訊與設定表','export-config','download')} 匯出後貼入 Google Sheet 第二個「Setting」分頁。</p></section>${apiTestCard()}<section class="panel wizard-card"><div class="wizard-section-heading"><div><h2>關鍵詞 → 顯示文字或網址</h2><p>由上往下比對，第一筆符合的規則回覆。完全不需要 AI 或 RAG。</p></div>${button('新增關鍵詞','add-rule','plus','primary')}</div><div class="rules-list">${state.rules.length?state.rules.map((r,i)=>`<article class="rule-card"><div class="rule-title"><span class="rule-order">${i+1}</span><strong>${escapeHTML(r.keyword)}</strong>${pill(r.enabled?'啟用':'停用',r.enabled?'':'gray')}${pill({exact:'完全符合',contains:'包含',prefix:'開頭符合'}[r.match],'gray')}</div><p class="rule-copy">${escapeHTML(r.text)}</p>${r.type==='url'?`<a class="rule-url" href="${escapeHTML(r.url)}" target="_blank" rel="noopener noreferrer">${escapeHTML(r.url)}</a>`:''}<div class="rule-actions"><button class="btn small" data-rule-edit="${r.id}">編輯</button><button class="btn small" data-rule-toggle="${r.id}">${r.enabled?'停用':'啟用'}</button>${i?`<button class="btn small" data-rule-up="${r.id}" aria-label="將 ${escapeHTML(r.keyword)} 規則上移">↑ 上移</button>`:''}<button class="btn small danger" data-rule-delete="${r.id}">移除</button></div></article>`).join(''):'<div class="empty">尚未設定關鍵詞，點「新增關鍵詞」開始。</div>'}</div><div class="sheet-sync"><strong>Google Sheet 同步</strong><p>${escapeHTML(runtime.sheetStatus)}</p><div class="actions">${button('授權／重新讀取','authorize-sheet','link')}${button('寫入 Google Sheet','write-rules','upload','primary')}${button('匯出規則 CSV','export-rules','download')}</div><p class="note">規則會寫入 Google Sheet 的「Keywords」工作表。日後可直接在該表新增或修改規則；GAS 每次處理訊息都會重新讀取，無須重新產生或部署程式。網頁修改先保存本機，按「寫入 Google Sheet」才同步。</p><details class="wizard-details"><summary>日後如何在 Google Sheet 新增規則？</summary><p>保留第一列欄名，每一列是一條規則。可複製既有列再修改，並給新規則不同的 ID。</p><div class="table-scroll"><table><thead><tr><th>欄位</th><th>填寫方式</th></tr></thead><tbody><tr><td>規則ID</td><td>不可重複，例如 rule-003；使用英文字母、數字、連字號或底線。</td></tr><tr><td>啟用</td><td>TRUE 啟用；FALSE 暫停。</td></tr><tr><td>關鍵詞</td><td>例如：營業時間。</td></tr><tr><td>比對方式</td><td>contains 包含、exact 完全符合、prefix 開頭符合。</td></tr><tr><td>回覆類型</td><td>text 顯示文字；url 顯示文字與連結。</td></tr><tr><td>顯示文字</td><td>例如：週一至週五 09:00–18:00。</td></tr><tr><td>網址</td><td>url 類型填入 http 或 https 網址；text 類型留空。</td></tr></tbody></table></div><p class="note">由上往下比對，第一筆符合就回覆；調整列順序即可改變優先順序。目前網頁同步支援最多 100 筆規則。</p><p class="note">在 Google Sheet 修改後，若要回網頁繼續編輯，先按「授權／重新讀取」並選「載入 Google 規則」。網頁寫入會以本機規則取代該表 A:G，請勿用舊資料覆蓋新增規則。</p></details></div></section>`}
function editRule(id){const r=state.rules.find(r=>r.id===id)||{id:uid(),enabled:true,keyword:'',match:'contains',type:'text',text:'',url:''};openModal(id?'編輯關鍵詞規則':'新增關鍵詞規則',`<input id="rule-id" type="hidden" value="${r.id}"><label class="field"><span>關鍵詞</span><input id="rule-keyword" maxlength="200" value="${escapeHTML(r.keyword)}" placeholder="例如：報名"></label><div class="field-grid"><label class="field"><span>比對方式</span><select id="rule-match">${[['contains','包含關鍵詞'],['exact','完全符合'],['prefix','以關鍵詞開頭']].map(([v,t])=>`<option value="${v}" ${r.match===v?'selected':''}>${t}</option>`).join('')}</select></label><label class="field"><span>回覆類型</span><select id="rule-type"><option value="text" ${r.type==='text'?'selected':''}>文字</option><option value="url" ${r.type==='url'?'selected':''}>文字＋網址</option></select></label></div><label class="field"><span>顯示文字</span><textarea id="rule-text" maxlength="4000" placeholder="例如：請點以下連結完成報名。">${escapeHTML(r.text)}</textarea></label><label class="field" id="rule-url-field" ${r.type==='text'?'hidden':''}><span>網址</span><input id="rule-url" type="url" maxlength="1000" value="${escapeHTML(r.url)}" placeholder="https://…"></label><div id="rule-error" class="modal-error" aria-live="polite"></div>`,button('取消','close-modal')+`<button class="btn primary" data-action="save-rule">保存規則</button>`)}
actions['add-rule']=()=>editRule();actions['save-rule']=()=>{const id=document.querySelector('#rule-id').value,old=state.rules.find(r=>r.id===id);const r={id,enabled:old?.enabled??true,keyword:document.querySelector('#rule-keyword').value.trim(),match:document.querySelector('#rule-match').value,type:document.querySelector('#rule-type').value,text:document.querySelector('#rule-text').value.trim(),url:document.querySelector('#rule-url').value.trim()};if(r.type==='text')r.url='';const updated=old?state.rules.map(x=>x.id===id?r:x):[...state.rules,r],error=ruleError(updated);if(error){document.querySelector('#rule-error').textContent=error;return}state.rules=updated;save();closeModal();render();toast('已保存本機規則，可按「寫入 Google Sheet」同步。')};
function matchRule(text,rules=state.rules){return rules.find(r=>r.enabled&&(r.match==='exact'?text===r.keyword:r.match==='prefix'?text.startsWith(r.keyword):text.includes(r.keyword)))}
function ruleReply(rule){return rule.text+(rule.type==='url'?'\n'+rule.url:'')}
const baseAsk=ask;
ask=function(question){question=question.trim();if(!question||question.length>1000)return;const rule=matchRule(question);let text,citations=[];if(rule)text=ruleReply(rule);else if(state.config.ragEnabled){const hits=retrieve(question);text=hits.length?'本機文件片段（非 AI 回答）：\n\n'+hits.map(h=>h.text).join('\n\n'):state.config.fallback;citations=hits}else text=state.config.fallback;chatMessages.push({role:'user',text:question},{role:'assistant',text,citations});if(page==='test')renderChat();return {mode:rule?'keyword-rule':state.config.ragEnabled?'local-document-search':'fallback',matched:!!rule,text}};
function exportRules(){const rows=[['規則ID','啟用','關鍵詞','比對方式','回覆類型','顯示文字','網址'],...state.rules.map(r=>[r.id,r.enabled?'TRUE':'FALSE',r.keyword,r.match,r.type,r.text,r.url])];download('Keywords.csv','\uFEFF'+rows.map(r=>r.map(csvCell).join(',')).join('\r\n'),'text/csv')}
actions['export-rules']=exportRules;
let gisPromise;
function loadGIS(){if(window.google?.accounts?.oauth2)return Promise.resolve();if(!gisPromise)gisPromise=new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='https://accounts.google.com/gsi/client';s.async=true;s.onload=resolve;s.onerror=()=>{gisPromise=null;reject(Error('Google 授權元件無法載入。'))};document.head.appendChild(s)});return gisPromise}
function authorizeSheetDialog(){openModal('連接 Google Sheet',`<label class="field"><span>Google Sheets 網址</span><input id="google-sheet-url" value="${escapeHTML(state.config.sheetUrl)}" placeholder="https://docs.google.com/spreadsheets/d/…"></label><label class="field"><span>Google OAuth 用戶端 ID</span><input id="google-client-id" value="${escapeHTML(state.config.googleClientId||'')}" placeholder="…apps.googleusercontent.com"><small>這是公開的 Web 用戶端 ID，不是 Client Secret。需啟用 Sheets API，並將目前網站來源加到「授權 JavaScript 來源」。</small></label><div class="status-banner">目前來源：${escapeHTML(location.origin)}<br>授權可讀寫試算表；本功能只操作你指定的試算表。授權 Token 不會保存到磁碟。</div><div id="google-error" class="modal-error"></div><p class="note">若原表已有規則，會先顯示差異及選擇，避免直接覆寫。</p>`,button('取消','close-modal')+button('Google 授權並讀取','google-authorize','link','primary'));loadGIS().catch(e=>{const el=document.querySelector('#google-error');if(el)el.textContent=e.message})}
actions['authorize-sheet']=authorizeSheetDialog;actions['connect-sheet']=authorizeSheetDialog;
actions['google-authorize']=()=>{const url=document.querySelector('#google-sheet-url').value.trim(),clientId=document.querySelector('#google-client-id').value.trim();const error=document.querySelector('#google-error');if(!validGoogleUrl(url,'sheet')){error.textContent='請輸入正確的試算表網址。';return}if(!/^[\w.-]+\.apps\.googleusercontent\.com$/.test(clientId)){error.textContent='請輸入 Google Cloud 建立的 Web OAuth 用戶端 ID。';return}if(!window.google?.accounts?.oauth2){error.textContent='Google 授權元件尚未載入，請稍後再按一次。';return}state.config.sheetUrl=url;state.config.googleClientId=clientId;save();const id=url.match(/\/d\/([-\w]+)/)[1];const client=window.google.accounts.oauth2.initTokenClient({client_id:clientId,scope:'https://www.googleapis.com/auth/spreadsheets',callback:async response=>{if(response.error){error.textContent='Google 授權未完成，請重試。';return}runtime.googleToken=response.access_token;runtime.expiresAt=Date.now()+Number(response.expires_in||3600)*1000;runtime.sheetId=id;runtime.revision=null;closeModal();await readRulesFromGoogle()},error_callback:()=>{error.textContent='授權視窗被關閉或無法開啟，請允許彈出視窗再試。'}});client.requestAccessToken({prompt:'consent'})};
function googlePayload(action){if(!runtime.googleToken||runtime.expiresAt<=Date.now())throw Error('Google 授權已過期或尚未授權，請先按「授權／重新讀取」。');if(runtime.sheetId!==state.config.sheetUrl.match(/\/d\/([-\w]+)/)?.[1])throw Error('試算表來源已變更，請重新授權並讀取。');return {service:'sheets',action,googleToken:runtime.googleToken,spreadsheetId:runtime.sheetId}}
async function readRulesFromGoogle(){try{runtime.sheetStatus='正在讀取 Google Sheet…';render();const result=await callApi(googlePayload('read'));runtime.sheetTitle=result.title;runtime.remoteRules=result.rules;runtime.revision=result.revision;runtime.sheetStatus=`已讀取「${result.title}」：${result.rules.length} 筆雲端規則，尚未寫入。`;render();if(result.rules.length)openModal('選擇要使用的規則',`<p>Google Sheet 有 ${result.rules.length} 筆規則，本機有 ${state.rules.length} 筆。讀取不會改動 Google Sheet。</p><p>保留本機後，按「寫入 Google Sheet」會以本機規則取代「Keywords」A:G 的內容。</p>`,button('保留本機規則','keep-local-rules')+button('載入 Google 規則','load-remote-rules','download','primary'));else toast('已連接，可將本機規則寫入 Google Sheet。')}catch(e){runtime.sheetStatus=e.message;runtime.revision=null;render();toast(e.message)}}
actions['load-remote-rules']=()=>{state.rules=runtime.remoteRules||[];save();closeModal();render();toast('已將 Google 規則載入本機。')};actions['keep-local-rules']=()=>{closeModal();toast('已保留本機規則，尚未寫入 Google。')};
actions['write-rules']=()=>{try{googlePayload('write');if(!runtime.revision)throw Error('請先讀取 Google Sheet。');const error=ruleError(state.rules);if(error)throw Error(error);openModal('寫入 Google Sheet',`<p>將 ${state.rules.length} 筆本機規則寫入「${escapeHTML(runtime.sheetTitle)}」的「Keywords」工作表。</p><p>會更新此表 A:G 的規則內容，並清除已移除的舊規則列；其他工作表不變。</p>`,button('取消','close-modal')+button('確認寫入','confirm-write-rules','upload','primary'))}catch(e){toast(e.message)}};
actions['confirm-write-rules']=async()=>{closeModal();try{runtime.sheetStatus='正在寫入並讀回驗證…';render();const result=await callApi({...googlePayload('write'),rules:state.rules,revision:runtime.revision});runtime.revision=result.revision;runtime.sheetStatus=`已寫入並讀回驗證 ${result.written} 筆規則 · ${new Date().toLocaleTimeString()}`;render();toast('Google Sheet 寫入成功。')}catch(e){runtime.sheetStatus=e.message;runtime.revision=null;render();toast(e.message)}};
document.addEventListener('input',e=>{const t=e.target;if(t.id==='live-api-key'){runtime.keys[selectedProvider]=t.value;delete runtime.results[selectedProvider];const el=document.querySelector('#api-test-result');if(el)el.textContent='Key 已更換，請重新測試。'}if(t.id==='manual-model'){state.config.provider=selectedProvider;state.config.model=t.value.trim();save()}if(t.id==='rules-bot-name'){state.config.botName=t.value;save()}if(t.id==='rules-bot-description'){state.config.botDescription=t.value;save()}if(t.id==='rules-welcome'){state.config.welcomeMessage=t.value;save()}if(t.id==='rules-fallback'){state.config.fallback=t.value;save()}if(t.id==='live-role'||t.id==='rules-ai-prompt'){state.config.role=t.value;save()}});
document.addEventListener('change',e=>{if(e.target.id==='rule-type')document.querySelector('#rule-url-field').hidden=e.target.value!=='url';if(e.target.id==='ai-enabled'){state.config.aiEnabled=e.target.checked;save()}if(e.target.id==='rag-enabled'){state.config.ragEnabled=e.target.checked;save();render()}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.ruleEdit)editRule(b.dataset.ruleEdit);if(b.dataset.ruleToggle){const r=state.rules.find(r=>r.id===b.dataset.ruleToggle);r.enabled=!r.enabled;save();render()}if(b.dataset.ruleUp){const i=state.rules.findIndex(r=>r.id===b.dataset.ruleUp);if(i>0)[state.rules[i-1],state.rules[i]]=[state.rules[i],state.rules[i-1]];save();render()}if(b.dataset.ruleDelete)openModal('移除規則',`<p>移除本機規則後，需再次寫入 Google Sheet 才會同步移除雲端規則。</p>`,button('取消','close-modal')+`<button class="btn danger" data-remove-rule="${b.dataset.ruleDelete}">移除本機規則</button>`);if(b.dataset.removeRule){state.rules=state.rules.filter(r=>r.id!==b.dataset.removeRule);save();closeModal();render()}});
const originalConfigRows=configRows;
configRows=function(){return originalConfigRows().filter(r=>r[0]!=='RAG_ENABLED').concat([['AI_ENABLED',String(state.config.aiEnabled)],['RAG_ENABLED',String(state.config.ragEnabled)],['RULES_SHEET_NAME','Keywords'],['BOT_DESCRIPTION',state.config.botDescription],['WELCOME_MESSAGE',state.config.welcomeMessage]])};
const baseGenerateGas=generateGas;
generateGas=function(){let code=baseGenerateGas().replace('Relay Studio — GAS 唯讀整合範本','LineBot + RAG — 關鍵詞回覆範本').replace(' * SPREADSHEET_ID、CONFIG_SHEET_ID、RAG_ENDPOINT、RAG_TOKEN',' * 必填：SPREADSHEET_ID、CONFIG_SHEET_ID\n * 選配：AI_API_KEY（啟用 AI 時）、RAG_ENDPOINT / RAG_TOKEN（啟用 RAG 時）');
return code+`\n// 關鍵詞規則由專用工作表讀取，修改回覆不需要重新部署。\nfunction loadRules_() {\n  const sheet = spreadsheet_().getSheets().find(s => s.getName().toLowerCase() === 'keywords') || spreadsheet_().getSheetByName('關鍵詞觸發');\n  if (!sheet) throw new Error('請先寫入或匯入「Keywords」工作表');\n  const values = sheet.getDataRange().getDisplayValues();\n  const headers = values.shift();\n  const expected = ['規則ID','啟用','關鍵詞','比對方式','回覆類型','顯示文字','網址'];\n  if (JSON.stringify(headers.slice(0,7)) !== JSON.stringify(expected)) {\n    throw new Error('Keywords工作表格式不正確');\n  }\n  return values.filter(r => r[0] && r[1] === 'TRUE').map(r => ({\n    keyword:r[2], match:r[3], type:r[4], text:r[5], url:r[6] || ''\n  }));\n}\n\nfunction resolveKeywordReply_(message) {\n  const rule = loadRules_().find(r => {\n    if (!r.keyword) return false;\n    if (r.match === 'exact') return message === r.keyword;\n    if (r.match === 'prefix') return message.startsWith(r.keyword);\n    return message.includes(r.keyword);\n  });\n  if (!rule) return null;\n  if (rule.type === 'url' && !/^https?:\\/\\//.test(rule.url)) {\n    throw new Error('關鍵詞網址格式錯誤');\n  }\n  return rule.text + (rule.type === 'url' ? '\\n' + rule.url : '');\n}\n\nfunction handleTextMessage_(message) {\n  const reply = resolveKeywordReply_(String(message));\n  if (reply !== null) return reply;\n  const config = loadConfig_();\n  if (config.RAG_ENABLED === 'true') return askKnowledge_(message, config);\n  if (config.AI_ENABLED === 'true') return askAI_(message, config);\n  return config.NO_ANSWER_MESSAGE || '請輸入有效的關鍵詞。';\n}\n\n// 從 GAS 編輯器手動執行；不會發送 LINE 訊息。\nfunction testKeywordReply() {\n  return handleTextMessage_(${JSON.stringify(state.rules.find(r=>r.enabled)?.keyword||'你好')});\n}\n\nfunction askAI_(message, config) {\n  const key = properties_().getProperty('AI_API_KEY');\n  if (!key || !config.AI_MODEL) throw new Error('請先設定 AI_API_KEY 與 AI_MODEL');\n  const model = config.AI_MODEL.replace(/^models\\//, '');\n  const prompt = (config.AI_ROLE || '') + '\\n使用者：' + message;\n  let url, headers, body;\n  if (config.AI_PROVIDER === 'Gemini') {\n    url = 'https://generativelanguage.googleapis.com/v1beta/models/' + encodeURIComponent(model) + ':generateContent';\n    headers = { 'x-goog-api-key': key };\n    body = { contents:[{ parts:[{ text:prompt }] }], generationConfig:{ maxOutputTokens:1024 } };\n  } else if (config.AI_PROVIDER === 'OpenAI') {\n    url = 'https://api.openai.com/v1/responses';\n    headers = { Authorization:'Bearer ' + key };\n    body = { model:model, input:prompt, max_output_tokens:1024, store:false };\n  } else if (config.AI_PROVIDER === 'Grok') {\n    url = 'https://api.x.ai/v1/chat/completions';\n    headers = { Authorization:'Bearer ' + key };\n    body = { model:model, messages:[{role:'user',content:prompt}], max_tokens:1024, stream:false };\n  } else throw new Error('不支援的 AI 供應商');\n  const response = UrlFetchApp.fetch(url, {method:'post',contentType:'application/json',headers:headers,payload:JSON.stringify(body),muteHttpExceptions:true});\n  if (response.getResponseCode() !== 200) throw new Error('AI 呼叫失敗，狀態 ' + response.getResponseCode());\n  const data = JSON.parse(response.getContentText());\n  let text = '';\n  if (config.AI_PROVIDER === 'Gemini') text = (data.candidates?.[0]?.content?.parts || []).filter(p=>!p.thought).map(p=>p.text || '').join('\\n');\n  else if (config.AI_PROVIDER === 'OpenAI') text = (data.output || []).flatMap(o=>o.content || []).filter(c=>c.type==='output_text').map(c=>c.text).join('\\n');\n  else text = data.choices?.[0]?.message?.content || '';\n  return text || config.NO_ANSWER_MESSAGE;\n}\n`};
